import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
} from '../remotionShim';
// Start Google Fonts Loader
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
// End Google Fonts Loader



export type FlowingPathAnimationProps = Record<string, any>;

const FlowingPathAnimation: React.FC<FlowingPathAnimationProps> = ({
  backgroundColor1 = "#8c2897",
  backgroundColor2 = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  lineColor = "#ffffff",
  ballColor = "#ffffff",
  ballSize = 120,
  ballSpeed = 1,
  firstSentence = "Make animation like this in seconds with....",
  firstSentenceFontSize = 80,
  firstSentenceYOffset = -240,
  secondSentence = "Malloy Studio",
  secondSentenceFontSize = 120,
  secondSentenceYOffset = -240,
}) => {
  useFontLoader(["Inter", "Caveat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // The single source of truth for motion. The ball continuously moves right.
  // The speed is decoupled from durationInSeconds; default travel time is 8 seconds.
  const ballTravelFrames = (8 * fps) / ballSpeed;
  const ballX = interpolate(frame, [0, ballTravelFrames], [400, 4600]);

  // The camera locks onto the ball's movement during the descending slope.
  // It pans exactly the same distance the ball travels in that window, freezing it on screen.
  const cameraX = interpolate(ballX, [1000, 3200], [0, -2200], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Mathematically define the track
  const getPathY = (x: number) => {
    const highY = height * 0.5; // Starts in the middle
    const lowY = height * 0.8; // Drops down
    const curveStart = 1152;
    const curveEnd = 3072;

    if (x <= curveStart) return highY;
    if (x >= curveEnd) return lowY;

    // Smooth Cosine Interpolation for organic slope
    const p = (x - curveStart) / (curveEnd - curveStart);
    const ease = (1 - Math.cos(p * Math.PI)) / 2;
    return highY + (lowY - highY) * ease;
  };

  // Generate the SVG path data once
  const pathData = useMemo(() => {
    let d = `M 0 ${getPathY(0)} `;
    for (let x = 10; x <= width * 3; x += 20) {
      d += `L ${x} ${getPathY(x)} `;
    }
    return d;
  }, [width, height]);

  // Background style parsing
  const bgStyle = transparentBackground
    ? { backgroundColor: "transparent" }
    : {
        background: `linear-gradient(180deg, ${backgroundColor1} 0%, ${backgroundColor2} 100%)`,
      };

  return (
    <AbsoluteFill
      style={{ ...bgStyle, fontFamily: "Inter", overflow: "hidden" }}
    >
      {/* 
        Scene Container: 
        Wider than the canvas to allow the camera to pan across the landscape. 
      */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: width * 3,
          height,
          transform: `translateX(${cameraX}px)`,
          transition: "none",
        }}
      >
        {/* Glowing Track Line */}
        <svg
          width={width * 3}
          height={height}
          style={{ position: "absolute", overflow: "visible" }}
        >
          <path
            d={pathData}
            stroke={lineColor}
            strokeWidth={24}
            fill="none"
            opacity={0.25}
            style={{ filter: "blur(10px)", transition: "none" }}
          />
          <path
            d={pathData}
            stroke={lineColor}
            strokeWidth={10}
            fill="none"
            opacity={0.6}
            style={{ filter: "blur(4px)", transition: "none" }}
          />
          <path
            d={pathData}
            stroke="#ffffff"
            strokeWidth={3}
            fill="none"
            opacity={0.9}
            style={{ transition: "none" }}
          />
        </svg>

        {/* First Sentence Animation in 1 line */}
        <div
          style={{
            position: "absolute",
            left: 450,
            top: 400 + firstSentenceYOffset,
            display: "flex",
            gap: "20px",
            whiteSpace: "nowrap",
          }}
        >
          {firstSentence.split(" ").map((word, i) => {
            // Trigger appearance as the ball passes each word's approximate location
            const startFadeBallX = 500 + i * 200;

            const wordOpacity = interpolate(
              ballX,
              [startFadeBallX, startFadeBallX + 150],
              [0, 1],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );
            const wordYOffsetAnim = interpolate(
              ballX,
              [startFadeBallX, startFadeBallX + 150],
              [20, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );

            return (
              <div
                key={i}
                style={{
                  fontSize: firstSentenceFontSize,
                  fontWeight: 600,
                  color: "white",
                  opacity: wordOpacity,
                  transform: `translateY(${wordYOffsetAnim}px)`,
                  textShadow: "0 0 20px rgba(255,255,255,0.3)",
                  transition: "none",
                  letterSpacing: "-0.02em",
                }}
              >
                {word}
              </div>
            );
          })}
        </div>

        {/* Final Sentence Animation in 1 line */}
        <div
          style={{
            position: "absolute",
            left: 3100,
            top: height * 0.8 - 140 + secondSentenceYOffset, // Positions exactly matching the track's low point minus an offset
            display: "flex",
            gap: "20px",
            whiteSpace: "nowrap",
          }}
        >
          {secondSentence.split(" ").map((word, i) => {
            // Trigger appearance as the ball passes specific milestones on the flat section
            const startFadeBallX = 3100 + i * 180;

            const wordOpacity = interpolate(
              ballX,
              [startFadeBallX, startFadeBallX + 250],
              [0, 1],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );
            const wordYOffsetAnim = interpolate(
              ballX,
              [startFadeBallX, startFadeBallX + 250],
              [20, 0],
              {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
              }
            );

            return (
              <div
                key={i}
                style={{
                  fontFamily: "Caveat",
                  fontSize: secondSentenceFontSize,
                  fontWeight: 500,
                  color: "white",
                  opacity: wordOpacity,
                  transform: `translateY(${wordYOffsetAnim}px)`,
                  textShadow: "0 0 15px rgba(255,255,255,0.4)",
                  transition: "none",
                  letterSpacing: "-0.01em",
                }}
              >
                {word}
              </div>
            );
          })}
        </div>

        {/* The Rolling Ball */}
        <div
          style={{
            position: "absolute",
            left: ballX,
            top: getPathY(ballX),
            width: ballSize,
            height: ballSize,
            borderRadius: "50%",
            backgroundColor: ballColor,
            // translate(-50%, -100%) ensures the true bottom center of the ball touches the exact line coordinates
            transform: "translate(-50%, -100%)",
            boxShadow: `0 0 15px ${ballColor}90, 0 0 35px ${ballColor}50`,
            transition: "none",
          }}
        />
      </div>
    </AbsoluteFill>
  );
};

export default FlowingPathAnimation;